const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all migration files from the migrations directory
 * Returns files sorted alphabetically by filename
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files (files with .sql extension)
        const sqlFiles = files.filter(file => 
            file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
        );

        // Sort files alphabetically for consistent ordering
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

/**
 * Main migration function
 * Logs each migration file that would be applied
 */
function runMigrations() {
    console.log('Starting migrations...\n');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migration files found in ./migrations/');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration filename
    for (const file of migrationFiles) {
        console.log(`Would apply: ${file}`);
    }

    console.log(`\nTotal: ${migrationFiles.length} migration(s) would be applied`);
}

// Run the migrations
runMigrations();

module.exports = { getMigrationFiles, MIGRATIONS_DIR };

