const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Resolve database connection string from environment
 */
function resolveDatabaseUrl() {
    // Check for .env.test file in the current directory
    const envPath = path.join(__dirname, '.env.test');

    if (fs.existsSync(envPath)) {
        // Load environment variables from .env.test
        const envConfig = dotenv.parse(fs.readFileSync(envPath));

        if (envConfig.DATABASE_URL) {
            console.log(`Successfully connected to database (from ${envPath})`);
            return envConfig.DATABASE_URL;
        }
    }

    // Check for .env file as fallback
    const fallbackEnvPath = path.join(__dirname, '.env');
    if (fs.existsSync(fallbackEnvPath)) {
        const envConfig = dotenv.parse(fs.readFileSync(fallbackEnvPath));

        if (envConfig.DATABASE_URL) {
            console.log(`Successfully connected to database (from ${fallbackEnvPath})`);
            return envConfig.DATABASE_URL;
        }
    }

    console.log('No DATABASE_URL found in environment');
    return null;
}

