const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Parse .env file content into an object
 */
function parseEnv(content) {
    const result = {};
    const lines = content.split('\n');

    for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip empty lines and comments
        if (trimmedLine === '' || trimmedLine.startsWith('#')) {
            continue;
        }

        // Split on first = sign
        const eqIndex = trimmedLine.indexOf('=');
        if (eqIndex > 0) {
            const key = trimmedLine.substring(0, eqIndex).trim();
            const value = trimmedLine.substring(eqIndex + 1).trim();
            result[key] = value;
        }
    }

    return result;
}

/**
 * Resolve database connection string from environment
 */
function resolveDatabaseUrl() {
    // Check for .env.test file in the current directory
    const envPath = path.join(__dirname, '.env.test');

    if (fs.existsSync(envPath)) {
        // Load environment variables from .env.test
        const envContent = fs.readFileSync(envPath, 'utf8');
        const envConfig = parseEnv(envContent);

        if (envConfig.DATABASE_URL) {
            console.log(`Successfully connected to database (from ${envPath})`);
            return envConfig.DATABASE_URL;
        }
    }

    // Check for .env file as fallback
    const fallbackEnvPath = path.join(__dirname, '.env');
    if (fs.existsSync(fallbackEnvPath)) {
        const envContent = fs.readFileSync(fallbackEnvPath, 'utf8');
        const envConfig = parseEnv(envContent);

        if (envConfig.DATABASE_URL) {
            console.log(`Successfully connected to database (from ${fallbackEnvPath})`);
            return envConfig.DATABASE_URL;
