const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get sorted list of migration files from the migrations directory
 * @returns {string[]} Array of migration filenames in order
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    return [];
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only SQL files (files with .sql extension)
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files alphabetically to ensure consistent ordering
  // This assumes migration files follow a naming convention like:
  // - 001_create_users.sql
  // - 002_add_email_column.sql
  // - etc.
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting database migration...');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/ directory.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s).`);
  console.log('Listing files that would be applied in order:');

  // Log each filename that would be applied
  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\nMigration listing complete.');
  console.log('Note: This script currently only logs the files that would be applied.');
  console.log('To actually apply the migrations, you would need to implement the database connection and SQL execution logic.');
}

// Run the migration script
runMigrations();

