// Directory containing SQL migration files
const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL files from the migrations directory and logs each filename in order
 * @returns {Promise<void>}
 */
async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (ending with .sql)
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically for consistent ordering

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return;
    }

    // Log each filename that would be applied
    console.log('Found migration files to apply (in order):');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${sqlFiles.length} migration file(s) found.`);
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

