// Directory containing SQL migration files
const MIGRATIONS_DIR = './migrations';

/**
 * Resolves database connection string from .env.test
 * @returns {string|null}
 */
function resolveDatabaseUrl() {
  const envFile = path.resolve(__dirname, '.env.test');

  if (fs.existsSync(envFile)) {
    // Simple .env parser (dotenv-free implementation)
    const envContent = fs.readFileSync(envFile, 'utf8');
    const envLines = envContent.split('\n');

    for (const line of envLines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) continue;

      // Parse KEY=VALUE format
      const eqIndex = trimmedLine.indexOf('=');
      if (eqIndex > 0) {
        const key = trimmedLine.substring(0, eqIndex).trim();
        const value = trimmedLine.substring(eqIndex + 1).trim();

        if (key === 'DATABASE_URL') {
          return value;
        }
      }
    }
  }

  return null;
}

/**
 * Reads SQL files from the migrations directory and logs each filename in order
 * @returns {Promise<void>}
 */
async function runMigrations() {
  try {
    // Resolve database connection string from .env.test
    const databaseUrl = resolveDatabaseUrl();

    if (databaseUrl) {
      console.log(`Connected to database: ${databaseUrl}`);
      console.log('Connected successfully (simulated - no actual connection made).');
    } else {
      console.log('DATABASE_URL not found in .env.test - skipping database connection.');
    }

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (ending with .sql)
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically for consistent ordering

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return;
    }

    // Log each filename that would be applied
    console.log('Found migration files to apply (in order):');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${sqlFiles.length} migration file(s) found.`);
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

