#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all migration files sorted by filename
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory not found:', MIGRATIONS_DIR);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  // Sort files alphabetically
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Apply migrations (log each filename that would be applied)
 */
function applyMigrations() {
  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log('Found', migrations.length, 'migration file(s):');

  migrations.forEach((migration, index) => {
    console.log(`${index + 1}. ${migration}`);
  });

  console.log('\nMigrations would be applied in the order above.');
}

// Run the migration script
applyMigrations();

