const MIGRATIONS_DIR = path.join(process.cwd(), 'migrations');

/**
 * Parse .env file and return environment variables
 * @param {string} envFile - Path to the .env file
 * @returns {object} Parsed environment variables
 */
function parseEnvFile(envFile) {
  const env = {};
  if (fs.existsSync(envFile)) {
    const content = fs.readFileSync(envFile, 'utf8');
    const lines = content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) continue;

      const [key, ...valueParts] = trimmed.split('=');
      if (key && valueParts.length > 0) {
        env[key.trim()] = valueParts.join('=').trim();
      }
    }
  }
  return env;
}

/**
 * Resolve database connection string from environment
 * @returns {string|null} Database URL or null if not found
 */
function resolveDatabaseUrl() {
  // Try to load from .env.test first
  const envPath = path.join(process.cwd(), '.env.test');
  const env = parseEnvFile(envPath);

  if (env.DATABASE_URL) {
    return env.DATABASE_URL;
  }

  // Fall back to process.env
  return process.env.DATABASE_URL || null;
}

