        if (res.statusCode === 200) {
          console.log('Audit service logged migration attempt successfully');
        } else {
          console.log(`Audit service returned status ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (e) => {
      console.log(`Could not send audit log: ${e.message}`);
