/**
 * Reads migration files from the migrations directory and logs each filename in order
 */
function runMigrations() {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        console.log('Migrations directory does not exist yet.');
        console.log('Creating migrations directory at:', MIGRATIONS_DIR);
        fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
        return;
    }

    // Get all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in', MIGRATIONS_DIR);
        return;
    }

    console.log('Found', sqlFiles.length, 'migration file(s):');
    sqlFiles.forEach(file => {
        console.log(file);
    });
