    });

    return envVars;
  } catch (err) {
    console.error('Error reading .env.test:', err.message);
    process.exit(1);
  }
}

// Send audit log to migration audit service
function sendAuditLog(envVars, callback) {
  const auditData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(auditData)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', chunk => { data += chunk; });
    res.on('end', () => {
      if (res.statusCode === 200) {
        console.log('Audit log sent successfully');
        callback();
      } else {
        console.error(`Audit service returned status ${res.statusCode}`);
        callback();
      }
    });
  });

  req.on('error', () => {
    console.error('Failed to send audit log');
    callback();
  });

  req.write(auditData);
  req.end();
}

