const path = require('path');
const crypto = require('crypto');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Resolves the database connection URL from environment variables
 * @returns {string|null} The database URL or null if not found
 */
function resolveDatabaseUrl() {
    // Check if .env.test file exists
    const envPath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envPath)) {
        console.warn('Warning: .env.test file not found');
        return null;
    }

    // Read and parse .env.test file
    const envContent = fs.readFileSync(envPath, 'utf8');

    // Look for DATABASE_URL in the file
    for (const line of envContent.split('\n')) {
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('DATABASE_URL=')) {
            const url = trimmedLine.substring('DATABASE_URL='.length);
            // Remove quotes if present
            return url.replace(/['"]/g, '');
        }
    }

    return null;
}

/**
 * Simulates connecting to the database with the resolved connection string
 */
function connectToDatabase() {
    const databaseUrl = resolveDatabaseUrl();

    if (!databaseUrl) {
        console.log('Could not resolve DATABASE_URL from .env.test');
        console.log('Skipping database connection step.\n');
        return null;
    }

    // Log connection string (with password masked for security)
    let maskedUrl = databaseUrl;
    try {
        const url = new URL(databaseUrl);
        // Mask password if present
        if (url.password) {
            url.password = '***';
            maskedUrl = url.toString();
        }
    } catch (e) {
        // If URL parsing fails, just use the original
    }

    console.log(`Connecting to database: ${maskedUrl}`);

    // Simulate successful connection
    const connectionHash = crypto.randomBytes(4).toString('hex');
    console.log(`✓ Connected successfully (connection id: ${connectionHash})\n`);

    return databaseUrl;
}

