    if (dbUrlMatch) {
      databaseUrl = dbUrlMatch[1];
      // Mask the password/secret for safe logging
      const maskedUrl = maskDatabaseUrl(databaseUrl);
      console.log('Loaded DATABASE_URL:', maskedUrl);
    }
  } else {
    console.log('.env.test file not found, using environment variable DATABASE_URL');
    databaseUrl = process.env.DATABASE_URL;
    if (databaseUrl) {
      console.log('Using DATABASE_URL from environment');
    }
  }

  // Simulate connection
  if (databaseUrl) {
    console.log('Connection established successfully');
  } else {
    console.log('No DATABASE_URL found, skipping connection');
  }

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('Migrations directory not found:', migrationsDir);
    return;
  }

  // Read all files in migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  console.log('\nLooking for migrations in:', migrationsDir);
  console.log('--------------------');

  if (sqlFiles.length === 0) {
    console.log('No SQL files found in migrations directory.');
    return;
  }

  console.log(`Found ${sqlFiles.length} SQL file(s) to process:\n`);

  // Log each filename in order
  for (const file of sqlFiles) {
    console.log('Would apply:', file);
  }
}

// Helper to mask sensitive parts of database URL for safe logging
function maskDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    // Replace password with asterisks
    return parsed.toString().replace(/:[^@]+@/, ':***@');
  } catch {
    // If URL parsing fails, just mask everything after the first colon
    return url.replace(/:\S+@/, ':***@');
  }
}

runMigrations().catch(console.error);

